public class InnerSessionSessionMonitoringConfigurationFactory(Action<Humidifier.EMR.SessionTypes.SessionMonitoringConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMR.SessionTypes.SessionMonitoringConfiguration>
{

    internal InnerSessionSessionS3LoggingConfigurationFactory S3LoggingConfigurationFactory { get; set; }

    internal InnerSessionSessionManagedLoggingConfigurationFactory ManagedLoggingConfigurationFactory { get; set; }

    internal InnerSessionSessionCloudWatchLoggingConfigurationFactory CloudWatchLoggingConfigurationFactory { get; set; }

    protected override Humidifier.EMR.SessionTypes.SessionMonitoringConfiguration Create()
    {
        var sessionMonitoringConfigurationResult = CreateSessionMonitoringConfiguration();
        factoryAction?.Invoke(sessionMonitoringConfigurationResult);

        return sessionMonitoringConfigurationResult;
    }

    private Humidifier.EMR.SessionTypes.SessionMonitoringConfiguration CreateSessionMonitoringConfiguration()
    {
        var sessionMonitoringConfigurationResult = new Humidifier.EMR.SessionTypes.SessionMonitoringConfiguration();

        return sessionMonitoringConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMR.SessionTypes.SessionMonitoringConfiguration result)
    {
        base.CreateChildren(result);

        result.S3LoggingConfiguration ??= S3LoggingConfigurationFactory?.Build();
        result.ManagedLoggingConfiguration ??= ManagedLoggingConfigurationFactory?.Build();
        result.CloudWatchLoggingConfiguration ??= CloudWatchLoggingConfigurationFactory?.Build();
    }

} // End Of Class

